model.source:
pub type Model {
  Model(title: String, message: String)
}

init.source:
pub fn init() -> #(Model, List(Effect(Msg))) {
  #(
    Model(title: "Hello from somewhere nice", message: "Wish you were here."),
    [],
  )
}

external.source:
@external(javascript, "./view.mjs", "view")
fn view(model: Model, dispatch: fn(Msg) -> Nil) -> Nil

pub fn main() -> fn() -> Nil {
  mvu.start(init(), update, view)
}

update.source:
pub type Msg {
  UserChangedTitle(String)
  UserChangedMessage(String)
}

pub fn update(model: Model, msg: Msg) -> #(Model, List(Effect(Msg))) {
  case msg {
    UserChangedTitle(title) -> #(Model(..model, title: title), [])
    UserChangedMessage(message) -> #(Model(..model, message: message), [])
  }
}

themes.source:
pub type Theme {
  Coral
  Ocean
  Meadow
}

pub fn theme_name(theme: Theme) -> String {
  case theme {
    Coral -> "coral"
    Ocean -> "ocean"
    Meadow -> "meadow"
  }
}

saveEffect.source:
export function saveDesign(title, message, theme) {
  return {
    perform: () => localStorage.setItem(key, JSON.stringify({ title, message, theme })),
    onSuccess: () => designSaved(),
    onFailure: () => storageFailed("Could not save. Browser storage may be unavailable."),
  }
}

restoreEffect.source:
export function loadDesign() {
  return {
    perform: () => localStorage.getItem(key),
    onSuccess: saved => saved === null ? storageWasEmpty() : storageReturnedDesign(saved),
    onFailure: () => storageFailed("Could not restore. Browser storage may be unavailable."),
  }
}
